{
  "entities": [
    {
      "name": "Basal Cell Skin Cancer",
      "type": "Concept",
      "description": "The most common type of skin cancer, also known as basal cell carcinoma (BCC), which is highly treatable and curable, especially when caught early."
    },
    {
      "name": "Skin",
      "type": "NaturalObject",
      "description": "The body's largest organ, acting as a barrier, with three layers: epidermis, dermis, and hypodermis."
    },
    {
      "name": "Epidermis",
      "type": "NaturalObject",
      "description": "The top layer of skin, providing a waterproof barrier and containing squamous cells, basal cells, and melanocytes."
    },
    {
      "name": "Dermis",
      "type": "NaturalObject",
      "description": "The middle layer of skin, containing connective tissue, blood vessels, oil and sweat glands, nerves, and hair follicles."
    },
    {
      "name": "Hypodermis",
      "type": "NaturalObject",
      "description": "The deepest tissue layer of skin, made up of fat and connective tissue."
    },
    {
      "name": "Basal Cells",
      "type": "Creature",
      "description": "Cells found in the lower part of the epidermis that constantly divide to form new cells replacing squamous cells on the skin's surface."
    },
    {
      "name": "Squamous Cells",
      "type": "Creature",
      "description": "Flat cells found in the upper part of the epidermis."
    },
    {
      "name": "Melanocytes",
      "type": "Creature",
      "description": "Cells located in the lower part of the epidermis that produce melanin, responsible for hair, skin, and eye color and protection from UV rays."
    },
    {
      "name": "Melanin",
      "type": "NaturalObject",
      "description": "A pigment responsible for hair, skin, and eye color, and filters out harmful UV rays."
    },
    {
      "name": "UV Radiation",
      "type": "Concept",
      "description": "Ultraviolet radiation from the sun or tanning beds that can damage DNA in skin cells, leading to skin cancer."
    },
    {
      "name": "DNA",
      "type": "Concept",
      "description": "The molecule that controls how cells grow and function; damage to DNA can cause cells to become abnormal."
    },
    {
      "name": "Surgery",
      "type": "Method",
      "description": "The most common treatment for basal cell skin cancer, involving removal of the cancer."
    },
    {
      "name": "Radiation Therapy",
      "type": "Method",
      "description": "A treatment option for basal cell skin cancer, using radiation to kill cancer cells."
    },
    {
      "name": "Systemic Therapy",
      "type": "Method",
      "description": "A treatment option for basal cell skin cancer that uses drugs to target cancer cells throughout the body."
    },
    {
      "name": "NCCN Guidelines for Patients",
