{
  "entities": [
    {
      "name": "Contrast Material",
      "type": "Concept",
      "description": "Substances used to improve the clarity of internal body images in CT and MRI scans. They are not dyes, are not permanent, and are excreted in urine. Their use may be avoided in cases of serious allergy or poor kidney function."
    },
    {
      "name": "CT Scan",
      "type": "Method",
      "description": "A computed tomography scan that uses x-rays and computer technology to create detailed images of the body. It takes multiple x-rays from different angles and combines them. Often used with contrast for cancer detection."
    },
    {
      "name": "MRI Scan",
      "type": "Method",
      "description": "A magnetic resonance imaging scan that uses radio waves and powerful magnets to produce images. It does not use x-rays. Contrast is often used. There are closed and open MRI designs, with closed being more common."
    },
    {
      "name": "PET Scan",
      "type": "Method",
      "description": "A positron emission tomography scan that uses a radioactive tracer to detect cancer cells. Cancer cells appear as bright spots, but not all bright spots are cancer. It can be combined with CT for a PET/CT scan."
    },
    {
      "name": "FDG-PET/CT",
      "type": "Method",
      "description": "A specific type of PET/CT scan using fluorodeoxyglucose (FDG) as a radiotracer. It requires fasting for at least 4 hours before the scan and is helpful when other imaging results are unclear."
    },
    {
      "name": "Ultrasound",
      "type": "Method",
      "description": "An imaging technique using high-energy sound waves to create pictures of the body. It is painless, does not use x-rays, and can be repeated. It is good at showing small areas of cancer in lymph nodes."
    },
    {
      "name": "Panoramic Dental X-ray",
      "type": "Method",
      "description": "A dental x-ray that captures the entire mouth in one image using a small dose of radiation. It is used by dentists and oral surgeons for planning treatments like dentures, braces, extractions, and implants."
    },
    {
      "name": "Biopsy",
      "type": "Method",
      "description": "A procedure that removes a sample of tissue or fluid for examination by a pathologist to confirm cancer presence and determine tumor histology. Types include fine-needle aspiration, fine-needle biopsy, and core needle biopsy."
    },
    {
      "name": "Biopsy of Metastasis",
      "type": "Method",
      "description": "A biopsy performed on a metastatic site to confirm the presence of cancer. The type of biopsy depends on the location of the suspected metastases."
    },
    {
      "name": "Smoking",
      "type": "Concept",
      "description": "The act of inhaling and exhaling smoke from tobacco products. It increases the risk of various cancers, can limit cancer treatment effectiveness, and impairs wound healing."
    },
    {
      "name": "Vaping",
      "type": "Concept",
      "description": "The act of inhaling vapor from electronic cigarettes or similar devices. It carries similar risks to smoking, including increased cancer risk and negative effects on treatment and healing."
    },
