{
  "entities": [
    {
      "name": "Bladder Cancer",
      "type": "Concept",
      "description": "A type of cancer that forms in the tissues of the bladder, often starting in the urothelial cells lining the inside of the bladder."
    },
    {
      "name": "Stage",
      "type": "Concept",
      "description": "A rating system used to describe the physical extent of cancer, indicating how far it has grown into the bladder wall and spread to other parts of the body. Stages range from 0 to 4."
    },
    {
      "name": "Grade",
      "type": "Concept",
      "description": "A rating of the aggressiveness of cancer, estimating how fast it is likely to grow and spread. Grades are either low grade (slow) or high grade (fast)."
    },
    {
      "name": "Bladder Wall",
      "type": "Location",
      "description": "The wall of the bladder, composed of four main layers: inner lining (urothelial layer), connective tissue layer, muscle layer, and outer fatty layer."
    },
    {
      "name": "Urothelial Layer",
      "type": "Location",
      "description": "The inner lining of the bladder wall, made of urothelial cells, where most bladder cancers start."
    },
    {
      "name": "Connective Tissue Layer",
      "type": "Location",
      "description": "The layer of the bladder wall beneath the inner lining, composed of connective tissue."
    },
    {
      "name": "Muscle Layer",
      "type": "Location",
      "description": "The layer of the bladder wall that cancer must invade to be considered muscle-invasive."
    },
    {
      "name": "Outer Fatty Layer",
      "type": "Location",
      "description": "The outermost layer of the bladder wall, composed of fatty tissue."
    },
    {
      "name": "Stage 0",
      "type": "Concept",
      "description": "The earliest stage of bladder cancer, affecting only the inner lining of the bladder. It has two subgroups: Stage 0a and Stage 0is."
    },
    {
      "name": "Stage 0a",
      "type": "Concept",
      "description": "A subgroup of Stage 0 bladder cancer where cancer cells grow from the inner lining toward the hollow center of the bladder, not into the bladder wall."
    },
    {
      "name": "Stage 0is",
      "type": "Concept",
      "description": "A subgroup of Stage 0 bladder cancer, also known as carcinoma in situ (CIS), characterized by a flat patch of cancer cells on the surface of the bladder lining that is fast-growing and aggressive."
    },
    {
      "name": "Stage 1",
      "type": "Concept",
      "description": "Bladder cancer that has grown through the inner lining into the connective tissue layer but has not invaded the muscle layer (non-muscle-invasive)."
    },
    {
      "name": "Stage 2",
      "type": "Concept",
      "description": "Bladder cancer that has grown into the muscle layer (muscle-invasive) but has not reached the fatty layer or spread elsewhere."
    },
    {
      "name": "Stage 3",
      "type": "Concept",
      "description": "Bladder cancer that has grown through the bladder wall into the fatty layer, possibly spreading to lymph nodes and nearby organs in the pelvis. It has two subgroups: Stage 3A and Stage 3B."
    },
    {
      "name": "Stage 3A",
      "type": "Concept",
      "description": "A subgroup of Stage 3 bladder cancer that may be only in the fatty tissue or spread to a single nearby lymph node, possibly invading nearby reproductive organs, but not spread to distant nodes or organs."
    },
    {
      "name": "Stage 3B",
      "type": "Concept",
      "description": "A subgroup of Stage 3 bladder cancer with the same traits as Stage 3A but has spread to multiple lymph nodes in the pelvis, not to distant nodes or organs."
    },
    {
      "name": "Stage 4",
      "type": "Concept",
      "description": "Bladder cancer that has grown through the bladder wall and may have spread to lymph nodes or organs far from the bladder. It has two subgroups: Stage 4A and Stage 4B."
    },
    {
      "name": "Stage 4A",
      "type": "Concept",
      "description": "A subgroup of Stage 4 bladder cancer that has invaded the wall of the pelvis or abdomen, or spread to lymph nodes far from the bladder."
    },
    {
      "name": "Stage 4B",
      "type": "Concept",
      "description": "A subgroup of Stage 4 bladder cancer that has spread to far away lymph nodes and organs like bones, liver, or lungs, representing metastatic bladder cancer."
    },
    {
      "name": "Carcinoma In Situ",
      "type": "Concept",
      "description": "A flat patch of cancer cells on the surface of the bladder lining that is fast-growing and aggressive, also known as Stage 0is."
    },
    {
      "name": "Low Grade",
      "type": "Concept",
      "description": "A grade of cancer indicating slow growth, abbreviated as LG."
    },
    {
      "name": "High Grade",
      "type": "Concept",
      "description": "A grade of cancer indicating fast growth, abbreviated as HG."
    },
    {
      "name": "Pathologist",
      "type": "Person",
      "description": "A medical professional who studies tumor samples in a laboratory to determine the cancer grade by comparing cancer cells to normal cells."
    },
    {
      "name": "Urothelial Cells",
      "type": "Concept",
      "description": "Cells that make up the inner lining of the bladder, where most bladder cancers start."
    },
    {
      "name": "SmokeFree.gov",
      "type": "Organization",
      "description": "A website providing online support for quitting smoking."
    },
    {
      "name": "BeTobaccoFree.gov",
      "type": "Organization",
      "description": "A website providing online support for quitting tobacco use."
    },
    {
      "name": "CDC.gov/tobacco",
      "type": "Organization",
      "description": "A website by the Centers for Disease Control and Prevention providing information and support for tobacco cessation."
    }
  ],
